/* isa_rt.c: the runtime under the instruction tests (isa_check.py). Each test's instruction is
 * generated by generate.py's translator into a C function (isa_<group>.c, built with this file);
 * this file gives it a flat 24-bit memory and stand-ins for the function table that record
 * where control went, runs every test from its initial state and compares the final one:
 * registers, SR, memory, next PC (or the exception vector taken), and cycles.
 * Built with -DISA_INTERP (and m68k_interp.c) it runs each test through the runtime's 68000
 * interpreter instead: one instruction, stopped at the next instruction boundary. */
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <genrecomp/genrecomp.h>
#include "isa_rt.h"

M68kContext g_m68k;
uint8_t g_m68k_irq_pending, g_m68k_ipc_kind;
unsigned int g_cyc, g_cyc_event, g_refresh, g_cyc_skip, g_m68k_icost, g_refresh_hold;
uint32_t g_m68k_pf, g_m68k_ipc, g_m68k_redirect, g_func_resume_pc;
unsigned g_irq_phase_at; bool g_irq_phase_set;

static uint8_t mem[1 << 24];
#ifdef ISA_INTERP
static jmp_buf s_stop;                           /* end of the interpreted instruction */
#endif
static uint32_t s_next;          /* where control went (call/tail/jsr/rts), 0xFFFFFFFF = fell through */
static int s_vector;             /* exception taken, -1 = none */
static uint16_t s_vec_sr;        /* SR when it was taken */
static uint32_t s_vec_regs[15];  /* D0-D7, A0-A6 then */

uint8_t bus_read8(uint32_t a) { return mem[a & 0xFFFFFF]; }
uint16_t bus_read16(uint32_t a) { a &= 0xFFFFFF; return (uint16_t)(mem[a] << 8 | mem[(a + 1) & 0xFFFFFF]); }
uint32_t bus_read32(uint32_t a) { return (uint32_t)bus_read16(a) << 16 | bus_read16(a + 2); }
void bus_write8(uint32_t a, uint8_t v) { mem[a & 0xFFFFFF] = v; }
void bus_write16(uint32_t a, uint16_t v) { bus_write8(a, (uint8_t)(v >> 8)); bus_write8(a + 1, (uint8_t)v); }
void bus_write32(uint32_t a, uint32_t v) { bus_write16(a, (uint16_t)(v >> 16)); bus_write16(a + 2, (uint16_t)v); }
uint8_t bus_ram_read8(uint16_t o) { return bus_read8(0xFF0000u | o); }
uint16_t bus_ram_read16(uint16_t o) { return bus_read16(0xFF0000u | o); }
uint32_t bus_ram_read32(uint16_t o) { return bus_read32(0xFF0000u | o); }
void bus_ram_write8(uint16_t o, uint8_t v) { bus_write8(0xFF0000u | o, v); }
void bus_ram_write16(uint16_t o, uint16_t v) { bus_write16(0xFF0000u | o, v); }
void bus_ram_write32(uint16_t o, uint32_t v) { bus_write32(0xFF0000u | o, v); }
#ifdef ISA_INTERP
/* the interpreter's check at the top of its loop (g_m68k_ipc_kind 1, ipc = the next PC): the
 * instruction is done, stop there; checks inside an instruction are ignored */
void bus_cycle_event(void) { if (g_m68k_ipc_kind == 1) longjmp(s_stop, 1); }
uint32_t g_jsr_from_interp, g_rts_orphan;
gen_func_t func_table_lookup(uint32_t a) { (void)a; return NULL; }
void report_unknown_isa(void) {}
#else
void bus_cycle_event(void) {}
#endif
void ps_itrace(uint32_t pc) { (void)pc; }

bool func_table_call(uint32_t t) { s_next = t & 0xFFFFFF; return true; }
bool func_table_call_expecting(uint32_t t, uint32_t r) { (void)r; return func_table_call(t); }
void func_table_tail(uint32_t t) { s_next = t & 0xFFFFFF; }
bool func_table_jsr(uint32_t t, uint32_t ret) {           /* as func_table.c: the return address pushed */
    g_m68k.a[7] -= 4; bus_write32(g_m68k.a[7], ret); s_next = t & 0xFFFFFF; return false;
}
void func_table_rts(void) { s_next = bus_read32(g_m68k.a[7]) & 0xFFFFFF; g_m68k.a[7] += 4; }
bool m68k_rte(uint32_t *pc) {                            /* as m68k.c outside an interrupt frame */
    uint32_t sp = g_m68k.a[7];
    uint16_t sr = bus_read16(sp);
    *pc = bus_read32(sp + 2) & 0xFFFFFF;
    g_m68k.a[7] = sp + 6;
    m68k_set_sr(sr);
    return true;
}
void recomp_m68k_exception(uint8_t v) {
    s_vector = v; s_vec_sr = m68k_get_sr();
    memcpy(s_vec_regs, g_m68k.d, 32); memcpy(s_vec_regs + 8, g_m68k.a, 28);
#ifdef ISA_INTERP
    longjmp(s_stop, 1);                            /* the test ends at the exception */
#endif
}

static const char *RN[19] = {"d0","d1","d2","d3","d4","d5","d6","d7","a0","a1","a2","a3","a4","a5","a6","usp","ssp","sr","pc"};

static void load(const uint32_t *r, const uint32_t *ram, int n) {
    for (int i = 0; i < n; i++) mem[ram[2 * i] & 0xFFFFFF] = (uint8_t)ram[2 * i + 1];
    memcpy(g_m68k.d, r, 32); memcpy(g_m68k.a, r + 8, 28);
    g_m68k.usp = r[15]; g_m68k.ssp = r[16];
    g_m68k.flag_S = (r[17] & 0x2000) != 0;          /* no stack swap while loading */
    m68k_set_sr((uint16_t)r[17]);
    g_m68k.a[7] = g_m68k.flag_S ? g_m68k.ssp : g_m68k.usp;
    g_m68k.pc = r[18];
}

int main(int argc, char **argv) {
    int verbose = argc > 1;
    int pass = 0, fail = 0, cyc_bad = 0;
    for (int k = 0; k < isa_ntests; k++) {
        const IsaTest *t = &isa_tests[k];
        load(t->init, isa_ram + 2 * t->ram0, t->nram0);
        g_cyc = 0; g_cyc_event = 0x40000000u; g_refresh = 0x40000000u; g_refresh_hold = 0; g_cyc_skip = 0;
        s_next = 0xFFFFFFFFu; s_vector = -1;
#ifdef ISA_INTERP
        g_cyc_event = 1;
        if (!setjmp(s_stop)) m68k_interp_run(t->init[18]);
        else s_next = g_m68k_ipc & 0xFFFFFF;           /* stopped at the next instruction */
        g_m68k_ipc = 0; g_m68k_ipc_kind = 0;
#else
        t->fn();
#endif
        if (g_m68k.flag_S) g_m68k.ssp = g_m68k.a[7]; else g_m68k.usp = g_m68k.a[7];
        char why[256] = "";
        const uint32_t *f = t->fin;
        if (t->vector >= 0) {                     /* exception: which one, and the state it saw */
            if (s_vector != t->vector)
                snprintf(why, sizeof why, "vector %d, expected %d", s_vector, t->vector);
            else {
                for (int i = 0; i < 15 && !*why; i++)
                    if (s_vec_regs[i] != f[i]) snprintf(why, sizeof why, "%s %08X, expected %08X", RN[i], s_vec_regs[i], f[i]);
                if (!*why && (s_vec_sr & 0xFF1F) != (t->vec_sr & 0xFF1F))
                    snprintf(why, sizeof why, "sr at exception %04X, expected %04X", s_vec_sr, t->vec_sr);
            }
        } else {
            uint32_t got[19];
            memcpy(got, g_m68k.d, 32); memcpy(got + 8, g_m68k.a, 28);
            got[15] = g_m68k.usp; got[16] = g_m68k.ssp; got[17] = m68k_get_sr();
            got[18] = s_next != 0xFFFFFFFFu ? s_next : (t->init[18] + t->len) & 0xFFFFFF;
            for (int i = 0; i < 19 && !*why; i++) {
                /* SR: the trace bit is not modelled (no game sets it); PC: the 24-bit bus */
                uint32_t m = i == 17 ? 0x271F : i == 18 ? 0xFFFFFF : 0xFFFFFFFF;
                if ((got[i] & m) != (f[i] & m)) snprintf(why, sizeof why, "%s %08X, expected %08X", RN[i], got[i], f[i]);
            }
            const uint32_t *r1 = isa_ram + 2 * t->ram1;
            for (int i = 0; i < t->nram1 && !*why; i++)
                if (mem[r1[2 * i] & 0xFFFFFF] != r1[2 * i + 1])
                    snprintf(why, sizeof why, "ram[%06X] %02X, expected %02X", r1[2 * i] & 0xFFFFFF, mem[r1[2 * i] & 0xFFFFFF], r1[2 * i + 1]);
        }
        for (int i = 0; i < t->nram0; i++) mem[isa_ram[2 * (t->ram0 + i)] & 0xFFFFFF] = 0;   /* clean slate */
        for (int i = 0; i < t->nram1; i++) mem[isa_ram[2 * (t->ram1 + i)] & 0xFFFFFF] = 0;
        unsigned cyc = g_cyc / 7;
        if (*why) { fail++; printf("FAIL\t%s\t%s\n", t->name, why); }
        else {
            pass++;
            if (t->vector < 0 && cyc != t->cycles) { cyc_bad++; if (verbose) printf("CYC\t%s\t%u, expected %u\n", t->name, cyc, t->cycles); }
        }
    }
    printf("TOTAL\t%d\t%d\t%d\n", pass, fail, cyc_bad);
    return 0;
}
